css:
.print-format {
  margin-top: 34mm;
  margin-bottom: 15mm;
  header-spacing: 3;
  margin-left: 15mm;
  margin-right: 15mm;
  font-size: 8.5pt;
}
html body .print-format, body .print-format { margin: 0 !important; padding: 0 !important; min-height: 0 !important; }
html body, body[onload] { padding: 0 !important; margin: 0 !important; }


.print-format .letter-head, .print-format .letter-head-footer, .letter-head, .letter-head-footer { display: none !important; }

.print-format, .print-format .afm, .print-format .afm td, .print-format .afm th, .print-format .afm div, .print-format .afm span, .print-format .afm p {
  font-family: "Noto Sans Arabic", "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm .en, .print-format .afm .num, .print-format .afm .ltr, .print-format .afm .en-l, .print-format .afm .num span, .print-format .afm .ltr2, .print-format .afm .cu, .print-format .afm-title .en-l {
  font-family: "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format { color: #171717; }
.print-format .afm { color: #171717; font-size: 8.5pt; line-height: 14px; font-weight: normal; -webkit-print-color-adjust: exact; }
.afm * { box-sizing: border-box; }
.print-format .afm p { margin: 0 !important; }
.afm b, .afm strong { font-weight: bold; }
.afm .num { white-space: nowrap; direction: ltr; unicode-bidi: embed; text-align: right; }
.afm .ctr { text-align: center !important; }
.afm .ltr { direction: ltr; unicode-bidi: embed; }


.print-format .section-break { margin: 0 0 8px 0 !important; padding: 0 !important; }


.afm .pair { display: table; width: 100%; line-height: 12px; }
.afm .pair .en { display: table-cell; text-align: left; white-space: nowrap; vertical-align: baseline; font-size: 6pt; line-height: 10px; color: #5f5f5f; padding: 0 4px 0 0; }
.afm .pair .ar { display: table-cell; text-align: right; white-space: nowrap; vertical-align: baseline; font-size: 7pt; line-height: 12px; color: #5f5f5f; direction: rtl; }


.afm-kv { margin: 0 0 4px 0; border-bottom: 0.75pt solid #d0d0d0; padding: 0 0 1px 0; }
.afm-kv .v { display: block; font-size: 8.5pt; line-height: 14px; color: #171717; white-space: nowrap; }
.afm-kv .v.wrap { white-space: normal; }
.afm-kv .v.b { font-weight: bold; }
.afm-kv .v .num { text-align: left; }


.afm-items-wrap { margin: 0; }
.print-format .afm table.afm-items { width: 100%; table-layout: fixed; border-collapse: collapse; margin: 0 !important; border: 0.75pt solid #d0d0d0; }
.afm-items thead { display: table-header-group; }
.afm-items tr { page-break-inside: avoid; }
.print-format .afm .afm-items th {
  background: #f4f4f4 !important;
  color: #171717 !important;
  border: 0.75pt solid #d0d0d0 !important;
  border-top: 1.2pt solid #00844e !important;
  padding: 1px 4px !important;
  vertical-align: bottom !important;
  text-align: left !important;
  font-weight: normal;
  white-space: nowrap;
}
.print-format .afm .afm-items th.r { text-align: right !important; }
.afm-items th .en { display: block; font-size: 6pt; line-height: 10px; color: #5f5f5f; white-space: nowrap; }
.afm-items th .ar { display: block; font-size: 7pt; line-height: 12px; color: #171717; font-weight: bold; white-space: nowrap; direction: rtl; }
.afm-items th .cu { display: block; font-size: 6pt; line-height: 10px; color: #5f5f5f; white-space: nowrap; }
.print-format .afm .afm-items td {
  border: 0.75pt solid #d0d0d0 !important;
  padding: 1px 4px !important;
  vertical-align: top !important;
  font-size: 8.5pt;
  line-height: 14px;
  background: #ffffff !important;
  word-wrap: break-word;
}
.print-format .afm .afm-items td.num { text-align: right !important; }
.afm-items .sub { display: block; font-size: 7pt; line-height: 12px; color: #5f5f5f; }


.afm-qr img { width: 96px; height: 96px; display: block; margin: 0 0 4px 0; }
.afm-qr .note { font-size: 7pt; line-height: 12px; color: #5f5f5f; }


.print-format .afm table.afm-tot { width: 100%; table-layout: fixed; border-collapse: collapse; margin: 0 !important; border: 0.75pt solid #d0d0d0; }
.print-format .afm .afm-tot td { border: 0.75pt solid #d0d0d0 !important; padding: 1px 4px !important; vertical-align: middle !important; background: #ffffff !important; }
.print-format .afm .afm-tot td.num { text-align: right !important; font-weight: bold; }
.print-format .afm .afm-tot tr.grand td { background: #00844e !important; color: #ffffff !important; border-color: #00844e !important; font-weight: bold; }
.afm-tot tr.grand .pair .en, .afm-tot tr.grand .pair .ar { color: #ffffff; }
.afm-tot tr.grand .pair .ar { font-weight: bold; }


.afm-notes { border-top: 1.2pt solid #00844e; padding: 1px 0 0 0; }
.afm-notes .pair { margin: 0 0 4px 0; }
.print-format .afm-notes p { font-size: 7pt; line-height: 12px; color: #171717; margin: 0 !important; }
.afm-notes .pair .ar { font-weight: bold; color: #00844e; }
.afm-notes .pair .en { color: #00844e; }


.afm-stamp { padding: 8px 0 0 0; }
.afm-stamp img { height: 80px; width: 170px; display: block; }


.afm-hdr table { width: 100%; border-collapse: collapse; table-layout: fixed; border-spacing: 0; }
.afm-hdr .logo img { height: 48px; width: auto; display: block; }
.print-format .afm-hdr td { padding: 0 !important; vertical-align: middle !important; border: 0 !important; }
.afm-hdr .ids td { font-size: 8.5pt; line-height: 14px; white-space: nowrap; vertical-align: baseline !important; }
.print-format .afm-hdr .ids td { padding: 0 4px 0 0 !important; }
.afm-hdr .ids td.num { text-align: right !important; }
.afm-hdr .ids .k { font-size: 7pt; color: #5f5f5f; }
.afm-hdr .ids .k.ltr { font-size: 6pt; }
.afm-hdr .rule td { height: 8px; }
.afm-hdr .rule .thin { border-bottom: 0.75pt solid #00844e !important; }
.afm-hdr .rule .thick { border-bottom: 2.4pt solid #00844e !important; }
.afm-title { text-align: center; padding: 4px 0 0 0; }
.afm-title .t { display: inline-block; font-size: 13pt; line-height: 20px; font-weight: bold; color: #171717; white-space: nowrap; border-bottom: 1.2pt solid #00844e; padding: 0 8px 1px 8px; }
.print-format [document-status] h4 { font-size: 8.5pt; line-height: 14px; color: #5f5f5f; }


.afm-ftr table { width: 100%; border-collapse: collapse; table-layout: fixed; border-spacing: 0; }
.print-format .afm-ftr td { border-top: 0.75pt solid #00844e !important; padding: 4px 0 0 0 !important; font-size: 7pt; line-height: 12px; color: #5f5f5f; vertical-align: top !important; }
.afm-ftr .ltr { white-space: nowrap; }
.afm-ftr .co { white-space: nowrap; }
.afm-ftr .ltr2 { direction: ltr; text-align: right; white-space: nowrap; padding: 0 4px 0 0; font-family: "Noto Sans", "DejaVu Sans", sans-serif; }
.afm-ftr .pg { white-space: nowrap; color: #171717; }


.print-format .page-break:last-child, .print-format .page-break:last-of-type { page-break-after: auto !important; }

